using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioNativeMoveValidation {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic;static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static Vector2[] candidates;static Vector2 start,last,sent;static int hot,nearest,moveControl,phase,sample,axis;static double deadline;static Vector3[] original;static HashSet<int> selected;static StringBuilder report=new StringBuilder();static List<double> dragTimes=new List<double>(),frameTimes=new List<double>();
 static void Before(SceneView s){if(s!=view)return;var center=editor.EditingPivotPosition;float size=HandleUtility.GetHandleSize(center)*StudioSettings.Current.handleSize;candidates=new[]{HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.5f),HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.7f),HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.9f),HandleUtility.WorldToGUIPoint(center)};}
 static void After(SceneView s){if(s!=view)return;hot=GUIUtility.hotControl;nearest=HandleUtility.nearestControl;moveControl=(int)typeof(StudioModelEditor).GetField("moveDragControl",F).GetValue(editor);}
 public static void Run(){EditorApplication.delayCall+=Begin;}
 static void Begin(){try{StudioMoveDragValidation.Validate();var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");var doc=StudioModelDocument.Import(model,"Assets/NativeMoveFrame.asset");controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(controller,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(controller,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(controller,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==controller);view.position=new Rect(0,0,1500,950);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(controller);editor.SelectObject(editor.Document.nodes.FindIndex(n=>n.name=="Body"&&n.mesh));typeof(StudioModelEditor).GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);typeof(StudioModelEditor).GetField("tool",F).SetValue(editor,Tool.Move);typeof(StudioModelEditor).GetField("local",F).SetValue(editor,false);var points=editor.ActiveMesh.vertices;float median=points.Select(p=>p.x).OrderBy(x=>x).ElementAt(points.Length/2);for(int i=0;i<points.Length;i++)if(points[i].x<median)editor.Components.Add(i);editor.Frame(view);StudioModelEditor.MoveHandleProbe=(center,size)=>{Event.current.mousePosition=sent;var offset=Vector2.zero;candidates=new[]{HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.5f)+offset,HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.7f)+offset,HandleUtility.WorldToGUIPoint(center+Vector3.right*size*.9f)+offset,HandleUtility.WorldToGUIPoint(center)+offset};};SceneView.duringSceneGui+=After;deadline=EditorApplication.timeSinceStartup+2;EditorApplication.update+=Tick;}catch(Exception ex){Finish(ex);}}
 static void Send(EventType kind,Vector2 point,Vector2 delta=default){sent=point;view.SendEvent(new Event{type=kind,button=0,mousePosition=new Vector2(700,400),delta=delta});}
 static void Tick(){if(EditorApplication.timeSinceStartup<deadline)return;try{if(phase==0){Send(EventType.Layout,new Vector2(700,400));Send(EventType.Repaint,new Vector2(700,400));var ids=(int[])typeof(StudioModelEditor).GetField("moveHandleIds",F).GetValue(editor);var choices=candidates.ToArray();bool found=false;foreach(var p in axis==0?choices.Take(3):choices.Skip(3)){Send(EventType.Layout,p);if(nearest==ids[axis==0?0:6]){start=p;found=true;break;}}if(!found)throw new Exception("No native move grip: nearest="+nearest+" ids="+string.Join(",",ids)+" points="+string.Join(";",choices));original=editor.ActiveMesh.vertices;selected=editor.SelectedVertices();Send(EventType.MouseDown,start);if(hot==0||moveControl!=hot)throw new Exception("Native Move did not capture: hot="+hot+" move="+moveControl);report.AppendLine("Captured "+(axis==0?"axis":"free")+" native control "+hot+", selected="+selected.Count);last=start;sample=0;phase=1;return;}
 if(phase==1){var point=start+new Vector2(sample%20*1.5f, sample%20*.4f);var timer=Stopwatch.StartNew();Send(EventType.MouseDrag,point,point-last);double drag=timer.Elapsed.TotalMilliseconds;Send(EventType.Layout,point);Send(EventType.Repaint,point);if(sample>=10){dragTimes.Add(drag);frameTimes.Add(timer.Elapsed.TotalMilliseconds);}last=point;if(++sample<50)return;var result=editor.ActiveMesh.vertices;var first=selected.First();var delta=result[first]-original[first];if(delta.sqrMagnitude<1e-10f)throw new Exception("Native gesture did not move geometry");foreach(int i in Enumerable.Range(0,result.Length))if((result[i]-original[i]-(selected.Contains(i)?delta:Vector3.zero)).sqrMagnitude>1e-10f)throw new Exception("Native move deformed selection instead of translating it");Send(EventType.MouseUp,last);if(hot!=0)throw new Exception("Native Move kept mouse capture after release");report.AppendLine((axis==0?"axis":"free")+" drag median ms="+dragTimes.OrderBy(x=>x).ElementAt(dragTimes.Count/2)+" combined median ms="+frameTimes.OrderBy(x=>x).ElementAt(frameTimes.Count/2)+" p95="+frameTimes.OrderBy(x=>x).ElementAt((int)Math.Ceiling(frameTimes.Count*.95)-1));dragTimes.Clear();frameTimes.Clear();if(++axis<2){phase=0;return;}Finish(null);}}
 catch(Exception ex){Finish(ex);}}
 static void Finish(Exception ex){EditorApplication.update-=Tick;StudioModelEditor.MoveHandleProbe=null;SceneView.duringSceneGui-=After;if(ex!=null)report.AppendLine(ex.ToString());else report.AppendLine("PASS native axis/free MouseDown/MouseDrag/MouseUp, translated geometry, unchanged unselected points and capture release");File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../native-move-validation.txt")),report.ToString());if(view)view.Close();if(controller)Object.DestroyImmediate(controller);EditorApplication.Exit(ex==null?0:1);}
}
